    2 * size_of::<OnePassByteCall<'static>>() + 2 * size_of::<Result<(), Diagnostic>>();
pub(super) const ONE_PASS_VECTOR_CALL: usize =
    2 * size_of::<OnePassVectorCall<'static>>() + 2 * size_of::<Result<(), Diagnostic>>();
