pub(super) const ONE_PASS_UNIT_ABI: usize =
    2 * size_of::<OnePassByteCall<'static>>() + 2 * size_of::<Result<(), Diagnostic>>();
pub(super) const ONE_PASS_NODE_ABI: usize =
    2 * size_of::<OnePassNodeCall<'static>>() + 2 * size_of::<Result<(), Diagnostic>>();
