        + 2 * size_of::<Result<SharedWeighted, Diagnostic>>();
pub(super) const ONE_PASS_INLINE_PUBLISH_PAYMENTS: usize = ONE_PASS_UNIT_ABI
    + ONE_PASS_UNIT_ABI
    + ONE_PASS_UNIT_ABI
    + ONE_PASS_UNIT_ABI
    + ONE_PASS_WEIGHTED_FINISH;
