//! Fixed diagnostic aggregate only: no allocation, authority, payer or gate input.
use super::*;
use std::cell::RefCell;
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub(super) struct Cell {
    pub attempts: usize,
    pub requested: usize,
    pub acquired: usize,
    pub primitive_banks: usize,
    pub refused: usize,
    pub selection_requested: usize,
}
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(super) struct Report {
    // [old/current][other/HIR/PLAN][general/unit]
    pub cells: [[[Cell; 2]; 3]; 2],
    pub complete: bool,
    pub function: usize,
    pub budget: usize,
    pub invocation: usize,
    pub foreign_observation: bool,
}
#[derive(Clone, Copy)]
struct Pending {
    old: usize,
    phase: usize,
    unit: usize,
    bytes: usize,
    banks: usize,
}
struct State {
    enabled: bool,
    phase: usize,
    serial: usize,
    report: Report,
    pending: Option<Pending>,
}
impl State {
    const fn new() -> Self {
        Self {
            enabled: false,
            phase: 0,
            serial: 0,
            report: Report {
                cells: [[[Cell {
                    attempts: 0,
                    requested: 0,
                    acquired: 0,
                    primitive_banks: 0,
                    refused: 0,
                    selection_requested: 0,
                }; 2]; 3]; 2],
                complete: true,
                function: 0,
                budget: 0,
                invocation: 0,
                foreign_observation: false,
            },
            pending: None,
        }
    }
}
thread_local! { static STATE: RefCell<State> = const { RefCell::new(State::new()) }; }
fn add(slot: &mut usize, value: usize, complete: &mut bool) {
    match slot.checked_add(value) {
        Some(n) => *slot = n,
        None => {
            *slot = usize::MAX;
            *complete = false;
        }
    }
}
pub(super) struct Observation {
    previous: bool,
}
pub(super) fn observe(function: &ResolvedFunction, budget: &ReplayBudget) -> Observation {
    STATE.with(|s| {
        let mut s = s.borrow_mut();
        let previous = s.enabled;
        assert!(!previous, "diagnostic observations are not nested");
        let mut complete = true;
        let mut serial = s.serial;
        add(&mut serial, 1, &mut complete);
        s.serial = serial;
        s.report = State::new().report;
        s.report.complete = complete;
        s.report.function = std::ptr::from_ref(function) as usize;
        s.report.budget = std::ptr::from_ref(budget) as usize;
        s.report.invocation = serial;
        s.enabled = true;
        s.pending = None;
        Observation { previous }
    })
}
pub(super) fn take() -> Report {
    STATE.with(|s| {
        let mut s = s.borrow_mut();
        if let Some(p) = s.pending.take() {
            let mut complete = s.report.complete;
            add(
                &mut s.report.cells[p.old][p.phase][p.unit].refused,
                1,
                &mut complete,
            );
            s.report.complete = complete;
        }
        s.report
    })
}
impl Drop for Observation {
    fn drop(&mut self) {
        STATE.with(|s| s.borrow_mut().enabled = self.previous);
    }
}
pub(in crate::cleanup_plan::replay::factored) struct Phase {
    previous: usize,
}
pub(in crate::cleanup_plan::replay::factored) fn phase(hir: bool) -> Phase {
    STATE.with(|s| {
        let mut s = s.borrow_mut();
        let previous = s.phase;
        s.phase = if hir { 1 } else { 2 };
        Phase { previous }
    })
}
impl Drop for Phase {
    fn drop(&mut self) {
        STATE.with(|s| s.borrow_mut().phase = self.previous);
    }
}
pub(in crate::cleanup_plan::replay::factored::canonical_shared) fn request(
    unit: bool,
    old: bool,
    warm: bool,
    function: &ResolvedFunction,
    budget: &ReplayBudget,
) {
    STATE.with(|s| {
        let mut s = s.borrow_mut();
        if !s.enabled {
            return;
        }
        if s.report.function != std::ptr::from_ref(function) as usize
            || s.report.budget != std::ptr::from_ref(budget) as usize
        {
            s.report.foreign_observation = true;
            s.report.complete = false;
            return;
        }
        if s.pending.is_some() {
            s.report.complete = false;
            return;
        }
        let old = usize::from(!old);
        let phase = s.phase;
        let unit = usize::from(unit);
        let bytes = if old == 0 {
            ORIGINAL_RECEIVING
        } else if warm {
            WARM_RECEIVING
        } else {
            COLD_RECEIVING
        };
        let banks = usize::from(old == 0 || !warm);
        let mut complete = s.report.complete;
        let c = &mut s.report.cells[old][phase][unit];
        add(&mut c.attempts, 1, &mut complete);
        add(&mut c.requested, bytes, &mut complete);
        if old == 1 {
            add(&mut c.selection_requested, PER_USE_SELECTION, &mut complete);
        }
        s.report.complete = complete;
        s.pending = Some(Pending {
            old,
            phase,
            unit,
            bytes,
            banks,
        });
    });
}
pub(in crate::cleanup_plan::replay::factored::canonical_shared) fn acquired() {
    STATE.with(|s| {
        let mut s = s.borrow_mut();
        if !s.enabled {
            return;
        }
        let Some(p) = s.pending.take() else {
            s.report.complete = false;
            return;
        };
        let mut complete = s.report.complete;
        let c = &mut s.report.cells[p.old][p.phase][p.unit];
        add(&mut c.acquired, p.bytes, &mut complete);
        add(&mut c.primitive_banks, p.banks, &mut complete);
        s.report.complete = complete;
    });
}
#[test]
fn fixed_successor_census_8769_rows_and_checked_overflow_are_diagnostic_only() {
    let mut count = 0;
    let mut complete = true;
    for _ in 0..8769 {
        add(&mut count, 1, &mut complete);
    }
    assert_eq!(count, 8769);
    assert!(complete);
    count = usize::MAX;
    add(&mut count, 1, &mut complete);
    assert_eq!(count, usize::MAX);
    assert!(!complete);
}

#[test]
fn all_twelve_census_cells_route_without_event_buffer_or_authority() {
    let program = crate::check("module c884; @id(\"main\") fn main()->i64{1}", "c884.spx").unwrap();
    let f = crate::hir::resolve(&program).unwrap().functions.remove(0);
    let b = ReplayBudget::unobserved();
    let guard = observe(&f, &b);
    // Diagnostic routing only: these calls do not reserve any real bytes and
    // their synthetic aggregate must never serve as an earned bill/fit claim.
    for phase_index in 0..3 {
        STATE.with(|s| s.borrow_mut().phase = phase_index);
        for old in [true, false] {
            for unit in [false, true] {
                for n in 0..8769 {
                    request(unit, old, n != 0, &f, &b);
                    acquired();
                }
            }
        }
    }
    let r = take();
    assert!(r.complete && !r.foreign_observation);
    assert_eq!(r.function, std::ptr::from_ref(&f) as usize);
    assert_eq!(r.budget, std::ptr::from_ref(&b) as usize);
    for old in 0..2 {
        for phase in 0..3 {
            for unit in 0..2 {
                let c = r.cells[old][phase][unit];
                let expected = if old == 0 {
                    8769 * ORIGINAL_RECEIVING
                } else {
                    COLD_RECEIVING + 8768 * WARM_RECEIVING
                };
                assert_eq!(
                    (c.attempts, c.requested, c.acquired, c.refused),
                    (8769, expected, expected, 0)
                );
                assert_eq!(c.primitive_banks, if old == 0 { 8769 } else { 1 });
            }
        }
    }
    drop(guard);
}

//! The actual retained canonical frame-loop method, not a forwarding adapter.
use super::super::*;

impl Canonicalizer<'_> {
    pub(in crate::cleanup_plan::replay::factored::canonical_shared) fn id_inner_into(
        &mut self,
        function: &ResolvedFunction,
        root: Weighted,
        budget: &mut ReplayBudget,
        receiving: &mut closure_receiving::ClosureReceiving,
    ) {
        macro_rules! attempt {
            ($operation:expr) => {
                match $operation {
                    Ok(value) => value,
                    Err(error) => {
                        receiving.refusal = Some(error);
                        receiving.ready = true;
                        return;
                    }
                }
            };
        }
        self.successor_unit_paid = false;
        self.successor_general_paid = false;
        receiving.overflow = false;
        attempt!(budget.reserve_vec(
            function,
            &mut self.frames,
            1,
            "factored canonical initial frame",
        ));
        // This direct root construction has no Diagnostic-bearing helper Result.
        // Both enum values, actual Rc initializer/receiving values and payment
        // Result remain real and prepaid; the general successor helper is unchanged.
        if budget.pays_allocations() {
            attempt!(budget.reserve_bytes(
                function,
                2 * std::mem::size_of::<SmallWeighted>()
                    + 2 * std::mem::size_of::<SharedWeighted>()
                    + std::mem::size_of::<Result<(), Diagnostic>>(),
                "factored direct root enum receiving",
            ));
        }
        attempt!(budget.reserve_bytes(
            function,
            physical_clone::rc_backing_bytes::<SmallWeighted>(),
            "factored weighted shared header",
        ));
        let shared = SmallWeighted::Many(root);
        let root = Rc::new(shared);
        let root_copy = attempt!(share_weighted(function, budget, &root));
        self.frames.push(CanonicalFrame::Enter(root_copy));
        while let Some(frame) = self.frames.pop() {
            attempt!(budget.charge(function, 1, "factored canonical frame"));
            match frame {
                CanonicalFrame::Enter(state) => {
                    if self.states.contains_key(&state) {
                        continue;
                    }
                    if self.open.contains(&state) {
                        receiving.refusal =
                            Some(replay_error(function, "cleanup CFG contains a cycle"));
                        receiving.ready = true;
                        return;
                    }
                    attempt!(budget.reserve_vec(
                        function,
                        &mut self.open,
                        1,
                        "factored retained open-state identity slots",
                    ));
                    self.open
                        .push(attempt!(share_weighted(function, budget, &state)));
                    let Some((accepted, successors)) = (match budget {
                        ReplayBudget {
                            payer: AllocationPayer::ActiveBuilder,
                            ..
                        } => lexical_successors!(self, function, state, budget, receiving, attempt),
                        _ => attempt!(
                            self.successors_with_receiving(function, &state, budget, receiving)
                        ),
                    }) else {
                        receiving.finish_overflow();
                        return;
                    };
                    let child_count = successors.len();
                    attempt!(budget.reserve_vec(
                        function,
                        &mut self.frames,
                        1,
                        "factored canonical exit frame",
                    ));
                    let exit_index = self.frames.len();
                    self.frames
                        .push(CanonicalFrame::Exit(state, accepted, successors));
                    for index in 0..child_count {
                        let CanonicalFrame::Exit(_, _, successors) = &self.frames[exit_index]
                        else {
                            unreachable!("canonical exit retained below child frames");
                        };
                        let child =
                            attempt!(share_weighted(function, budget, &successors[index].1));
                        attempt!(budget.reserve_vec(
                            function,
                            &mut self.frames,
                            1,
                            "factored canonical child frames",
                        ));
                        self.frames.push(CanonicalFrame::Enter(child));
                    }
                }
                CanonicalFrame::Exit(state, accepted, successors) => {
                    self.open.retain(|entry| entry != &state);
                    attempt!(budget.charge(
                        function,
                        successors.len(),
                        "factored canonical signature construction",
                    ));
                    // The old signature-work debit above remains first. Acquire
                    // the actual new branch receivers before evaluating the guard.
                    if budget.pays_allocations() {
                        attempt!(budget.reserve_bytes(
                            function,
                            empty_signature::BRANCH_CONTROLS,
                            "canonical empty signature branch receiving",
                        ));
                    }
                    if successors.is_empty() {
                        if budget.pays_allocations() {
                            attempt!(budget.reserve_bytes(
                                function,
                                empty_signature::EMPTY_CONTROLS,
                                "canonical empty signature receiving",
                            ));
                        }
                        self.child_ids.clear();
                        // Retain the original key-vector zero authentication;
                        // no child directory, borrowed query or Zip exists here.
                        attempt!(budget.reserve_array::<(Label, usize)>(
                            function,
                            0,
                            "factored canonical signature vector",
                        ));
                        let key = (accepted, Vec::new());
                        let id = match self.ids.get(&key) {
                            Some(id) => {
                                #[cfg(test)]
                                arena_tests::signature_lookup(true);
                                *id
                            }
                            None => {
                                #[cfg(test)]
                                arena_tests::signature_lookup(false);
                                intern_arena::prepare_insert!(
                                    self.ids,
                                    intern_arena::Signature,
                                    function,
                                    budget
                                );
                                let id = self.ids.len();
                                self.ids.insert_prepaid(key, id);
                                id
                            }
                        };
                        self.child_ids.clear();
                        if !self.states.contains_key(&state) {
                            intern_arena::prepare_insert!(
                                self.states,
                                SharedWeighted,
                                function,
                                budget
                            );
                        }
                        self.states.insert_prepaid(state, id);
                        continue;
                    }
                    attempt!(budget.reserve_bytes(
                        function,
                        intern_arena::SignatureQuery::LEXICAL_EXIT_CONTROLS,
                        "canonical borrowed signature receiving",
                    ));
                    // Retained scalar scratch contains only the child IDs for
                    // this frame; the epsilon cursor keeps its original shape.
                    self.child_ids.clear();
                    lexical_child_scratch::prepare!(self, successors, function, budget, receiving);
                    attempt!(budget.reserve_array::<[usize; 2]>(
                        function,
                        successors.len(),
                        "canonical child identity receiving",
                    ));
                    // Resolve every ID before signature comparison can stop at
                    // its first mismatch. This preserves the original failure order.
                    for (_, child) in &successors {
                        let Some(id) = self.states.get(child) else {
                            receiving.refusal =
                                Some(replay_error(function, "cleanup CFG contains a cycle"));
                            receiving.ready = true;
                            return;
                        };
                        self.child_ids.push(*id);
                    }
                    let query = intern_arena::SignatureQuery {
                        accepted,
                        successors: &successors,
                        children: &self.child_ids,
                    };
                    let id = match self.ids.get(&query) {
                        Some(id) => {
                            #[cfg(test)]
                            arena_tests::signature_lookup(true);
                            *id
                        }
                        None => {
                            #[cfg(test)]
                            arena_tests::signature_lookup(false);
                            attempt!(budget.reserve_array::<(Label, usize)>(
                                function,
                                successors.len(),
                                "factored canonical signature vector",
                            ));
                            // Every ID is already resolved. Move each original
                            // label with its borrowed ID, without an owned
                            // scalar cursor or repeated index/increment operands.
                            attempt!(budget.reserve_bytes(
                                function,
                                intern_arena::SignatureQuery::MISS_CONTROLS,
                                "canonical signature miss iterator receiving",
                            ));
                            attempt!(budget.reserve_array::<[&usize; 2]>(
                                function,
                                successors.len(),
                                "canonical signature miss borrowed IDs",
                            ));
                            let mut key = Vec::with_capacity(successors.len());
                            for ((label, _child), id) in successors.into_iter().zip(&self.child_ids)
                            {
                                key.push((label, *id));
                            }
                            let key = (accepted, key);
                            intern_arena::prepare_insert!(
                                self.ids,
                                intern_arena::Signature,
                                function,
                                budget
                            );
                            let id = self.ids.len();
                            self.ids.insert_prepaid(key, id);
                            id
                        }
                    };
                    self.child_ids.clear();
                    if !self.states.contains_key(&state) {
                        intern_arena::prepare_insert!(
                            self.states,
                            SharedWeighted,
                            function,
                            budget
                        );
                    }
                    self.states.insert_prepaid(state, id);
                }
            }
        }
        match self.states.get(&root) {
            Some(id) => receiving.id = *id,
            None => receiving.overflow = true,
        }
        receiving.ready = true;
    }
}

//! Authored owning controls; no execution or application saving is implied.
use super::*;
use crate::bounded_output::{with_limit_usage_refusal, with_limit_usage_refusal_site};
use crate::test_allocation_observer::{measure, Metrics};
// These are genuine new TEST caller transports, paid equally for both real
// old/current method calls; they confer no authority and do not pad old tariffs.
const ID_CALL_CONTROLS: usize = 2 * size_of::<(
    &mut Canonicalizer<'static>,
    &ResolvedFunction,
    Weighted,
    &mut ReplayBudget,
)>() + 2 * size_of::<Result<Option<usize>, Diagnostic>>()
    + 2 * size_of::<Weighted>();
fn function() -> ResolvedFunction {
    let p=crate::check("module lexical884; @id(\"f\") fn f(a:bool)->i64{if a{1}else{2}} @id(\"main\") fn main()->i64{f(true)}","lexical884.spx").unwrap();
    crate::hir::resolve(&p).unwrap().functions.remove(0)
}
fn graph(
    f: &ResolvedFunction,
    length: usize,
    branches: usize,
    cycle: bool,
) -> (Automaton, usize, usize) {
    let mut a = Automaton::default();
    let mut b = ReplayBudget::unobserved();
    let sink = a.node(f, &mut b).unwrap();
    let mut next = sink;
    for index in 0..length {
        let node = a.node(f, &mut b).unwrap();
        for branch in 0..branches {
            let terminal = if branch % 2 == 0 {
                super::super::super::SkeletonTerminal::Success
            } else {
                super::super::super::SkeletonTerminal::Failure
            };
            let child = if branch >= 2 && branch != 4 {
                let alternate = a.node(f, &mut b).unwrap();
                a.movement(
                    f,
                    &mut b,
                    alternate,
                    Label::End(super::super::super::SkeletonTerminal::Failure),
                    next,
                )
                .unwrap();
                alternate
            } else {
                next
            };
            a.movement(f, &mut b, node, Label::End(terminal), child)
                .unwrap();
        }
        if cycle && index == 0 {
            a.movement(
                f,
                &mut b,
                node,
                Label::End(super::super::super::SkeletonTerminal::Success),
                node,
            )
            .unwrap();
        }
        next = node;
    }
    (a, sink, next)
}
#[derive(Debug, PartialEq, Eq)]
struct Failure {
    code: &'static str,
    severity: crate::diagnostic::Severity,
    message: ([u8; 2048], usize),
    span: Option<crate::ast::Span>,
    path: Option<([u8; 2048], usize)>,
    help: Option<([u8; 2048], usize)>,
}
fn text(s: &str) -> ([u8; 2048], usize) {
    assert!(s.len() <= 2048);
    let mut b = [0; 2048];
    b[..s.len()].copy_from_slice(s.as_bytes());
    (b, s.len())
}
fn failure(d: Diagnostic) -> Failure {
    Failure {
        code: d.code,
        severity: d.severity,
        message: text(&d.message),
        span: d.span,
        path: d.path.as_deref().map(text),
        help: d.help.as_deref().map(text),
    }
}
#[derive(Debug, PartialEq, Eq)]
struct Outcome {
    result: Result<Option<usize>, Failure>,
    ordinary: usize,
    skeleton: usize,
    spent: usize,
    sticky: Option<Failure>,
    report: census::Report,
}
fn observe(
    old: bool,
    f: &ResolvedFunction,
    a: &Automaton,
    sink: usize,
    root: usize,
    weight: u64,
    limit: usize,
    floor: usize,
    work: usize,
) -> (
    (Outcome, Metrics),
    bool,
    usize,
    Option<crate::bounded_output::ReservationRefusal>,
    Option<(&'static str, u32)>,
) {
    let (value, refused, paid, receipt, site) = with_limit_usage_refusal_site(limit, || {
        measure(|| {
            let mut b = ReplayBudget::with_skeleton_limit(work);
            b.remaining = work;
            let observer = census::observe(f, &b);
            let _phase = census::phase(true);
            assert!(crate::bounded_output::set_active_floor(floor));
            let result = (|| {
                if old {
                    b.reserve_bytes(
                        f,
                        before_lexical_successors::Canonicalizer::CONSTRUCTOR_CONTROLS
                            + ID_CALL_CONTROLS,
                        "canonical ordered dictionary owner receiving",
                    )?;
                    let mut c = before_lexical_successors::Canonicalizer::new(a, sink);
                    b.reserve_array::<(usize, u64)>(f, 1, "884 root input")?;
                    c.id(f, vec![(root, weight)], &mut b)
                } else {
                    b.reserve_bytes(
                        f,
                        Canonicalizer::CONSTRUCTOR_CONTROLS + ID_CALL_CONTROLS,
                        "canonical ordered dictionary owner receiving",
                    )?;
                    let mut c = Canonicalizer::new(a, sink);
                    b.reserve_array::<(usize, u64)>(f, 1, "884 root input")?;
                    c.id(f, vec![(root, weight)], &mut b)
                }
            })();
            let (result, sticky) = match result {
                Ok(value) => (Ok(value), None),
                Err(error) => {
                    let selected = failure(error);
                    let bytes = crate::bounded_output::active_remaining();
                    let work = (b.remaining, b.skeleton_remaining, b.skeleton_spent);
                    let allocated = crate::test_allocation_observer::current_metrics().allocated;
                    let ledger =
                        crate::bounded_output::classifier_string::ClassifierLedger::capture();
                    let first = ledger.first_refusal();
                    // A semantic cycle diagnostic does not poison a budget. Only
                    // a real work/physical refusal has the sticky empty retry.
                    if !b.refusal_spent && first.is_none() {
                        (Err(selected), None)
                    } else {
                        let retry = failure(b.reserve_bytes(f, 0, "884 sticky retry").unwrap_err());
                        assert_eq!(bytes, crate::bounded_output::active_remaining());
                        assert_eq!(first, ledger.first_refusal());
                        assert_eq!(work, (b.remaining, b.skeleton_remaining, b.skeleton_spent));
                        assert_eq!(
                            allocated,
                            crate::test_allocation_observer::current_metrics().allocated
                        );
                        assert_eq!(retry, failure(Diagnostic::io("SPX-H006", String::new())));
                        (Err(selected), Some(retry))
                    }
                }
            };
            let value = Outcome {
                result,
                ordinary: b.remaining,
                skeleton: b.skeleton_remaining,
                spent: b.skeleton_spent,
                sticky,
                report: census::take(),
            };
            drop(observer);
            drop(b);
            crate::bounded_output::clear_active_floor();
            value
        })
    });
    assert!(!value.1.invalid);
    assert_eq!(value.1.live, 0);
    assert_eq!(value.1.allocated, value.1.freed);
    assert!(value.1.allocated <= paid && value.1.highwater <= paid);
    (
        value,
        refused,
        paid,
        receipt,
        site.map(|p| (p.file(), p.line())),
    )
}
#[test]
fn complete_immediate_canonicalizers_keep_every_state_signature_work_cut_cycle_and_overflow() {
    let f = function();
    for length in [0, 1, 4, 17] {
        for branches in [0, 1, 2, 3, 7] {
            if branches >= 3 && length > 4 {
                continue;
            }
            for weight in [0, 1, 2, u64::MAX] {
                let (a, sink, root) = graph(&f, length, branches, false);
                for work in [0, 1, 7, 31, MAX_REPLAY_WORK_UNITS] {
                    // Real work refusals poison their own invocation; compare separate
                    // complete ledgers rather than let old's refusal poison current.
                    let old = observe(true, &f, &a, sink, root, weight, 1 << 29, 0, work);
                    let current = observe(false, &f, &a, sink, root, weight, 1 << 29, 0, work);
                    assert_eq!(
                        old.0 .0.result, current.0 .0.result,
                        "all six work failures and canonical IDs"
                    );
                    assert_eq!(
                        (old.0 .0.ordinary, old.0 .0.skeleton, old.0 .0.spent),
                        (
                            current.0 .0.ordinary,
                            current.0 .0.skeleton,
                            current.0 .0.spent
                        )
                    );
                }
                with_limit_usage_refusal(1 << 29, || {
                    let mut x = ReplayBudget::new();
                    let mut y = ReplayBudget::new();
                    x.reserve_bytes(
                        &f,
                        before_lexical_successors::Canonicalizer::CONSTRUCTOR_CONTROLS
                            + ID_CALL_CONTROLS,
                        "884 actual old constructor and method callers",
                    )
                    .unwrap();
                    y.reserve_bytes(
                        &f,
                        Canonicalizer::CONSTRUCTOR_CONTROLS + ID_CALL_CONTROLS,
                        "884 actual current constructor and method callers",
                    )
                    .unwrap();
                    let mut old = before_lexical_successors::Canonicalizer::new(&a, sink);
                    let mut current = Canonicalizer::new(&a, sink);
                    x.reserve_array::<(usize, u64)>(&f, 1, "884 old root")
                        .unwrap();
                    y.reserve_array::<(usize, u64)>(&f, 1, "884 current root")
                        .unwrap();
                    assert_eq!(
                        old.id(&f, vec![(root, weight)], &mut x),
                        current.id(&f, vec![(root, weight)], &mut y)
                    );
                    old.assert_same(&current);
                });
            }
        }
    }
    let (a, sink, root) = graph(&f, 1, 1, true);
    let old = observe(
        true,
        &f,
        &a,
        sink,
        root,
        1,
        1 << 28,
        0,
        MAX_REPLAY_WORK_UNITS,
    );
    let current = observe(
        false,
        &f,
        &a,
        sink,
        root,
        1,
        1 << 28,
        0,
        MAX_REPLAY_WORK_UNITS,
    );
    assert_eq!(old.0 .0.result, current.0 .0.result);
    assert!(current.0 .0.result.is_err());
}
#[test]
fn actual_lexical_successor_reports_full_old_current_tuples_and_typed_break_even_without_credit() {
    let f = function();
    assert_eq!(ORIGINAL_RECEIVING, borrowed_labels::one_pass_receiving());
    for length in [0, 1, 4, 64] {
        for weight in [1, 2] {
            let (a, sink, root) = graph(&f, length, 2, false);
            let old = observe(
                true,
                &f,
                &a,
                sink,
                root,
                weight,
                1 << 29,
                0,
                MAX_REPLAY_WORK_UNITS,
            );
            let current = observe(
                false,
                &f,
                &a,
                sink,
                root,
                weight,
                1 << 29,
                0,
                MAX_REPLAY_WORK_UNITS,
            );
            assert_eq!(old.0 .0.result, current.0 .0.result);
            assert_eq!(
                (old.0 .0.ordinary, old.0 .0.skeleton, old.0 .0.spent),
                (
                    current.0 .0.ordinary,
                    current.0 .0.skeleton,
                    current.0 .0.spent
                )
            );
            assert!(!old.1 && !current.1);
            assert_eq!(old.0.1,current.0.1,"same real allocations, reallocations, peak and complete Drop; the candidate removes control frames");
            assert!(old.0 .0.report.complete && current.0 .0.report.complete);
            let old_cells = old.0 .0.report.cells[0][1];
            let cells = current.0 .0.report.cells[1][1];
            let n = cells.iter().map(|c| c.attempts).sum::<usize>();
            let m = cells.iter().map(|c| c.primitive_banks).sum::<usize>();
            assert_eq!(n, old_cells.iter().map(|c| c.attempts).sum::<usize>());
            assert!(m <= 2);
            let a = Canonicalizer::CONSTRUCTOR_CONTROLS
                .checked_sub(before_lexical_successors::Canonicalizer::CONSTRUCTOR_CONTROLS)
                .unwrap();
            let overhead = a + n * PER_USE_SELECTION;
            let gross = (n - m) * PRIMITIVE_FRAMES;
            assert_eq!(
                old.2.checked_add(overhead).unwrap(),
                current.2.checked_add(gross).unwrap(),
                "complete real bills reconcile without old padding/removed compound credit"
            );
            if gross > overhead {
                assert!(current.2 < old.2);
            }
            eprintln!("OPT884 length={length} weight={weight} N={n} M={m} P={PRIMITIVE_FRAMES} A={a} R={PER_USE_SELECTION} old/current paid={}/{} allocated={}/{} peak={}/{} work={}/{} census={:?}/{:?}",old.2,current.2,old.0.1.allocated,current.0.1.allocated,old.0.1.highwater,current.0.1.highwater,old.0.0.ordinary,current.0.0.ordinary,old.0.0.report,current.0.0.report);
        }
    }
}
fn primitive(
    f: &ResolvedFunction,
    requested: usize,
    remaining: usize,
    floor: usize,
) -> (Failure, Failure) {
    let ((first, sticky), refused, _, receipt) = with_limit_usage_refusal(usize::MAX, || {
        let mut b = ReplayBudget::new();
        b.prepare_builder(f).unwrap();
        let available = crate::bounded_output::active_remaining().unwrap();
        assert!(crate::bounded_output::reserve_active_required(
            available - remaining
        ));
        assert!(crate::bounded_output::set_active_floor(floor));
        let first = failure(
            b.reserve_bytes(f, requested, "factored one-pass label call receivers")
                .unwrap_err(),
        );
        let sticky = failure(b.reserve_bytes(f, 0, "884 sticky retry").unwrap_err());
        drop(b);
        crate::bounded_output::clear_active_floor();
        (first, sticky)
    });
    assert!(refused);
    let receipt = receipt.unwrap();
    assert_eq!(
        (receipt.requested, receipt.remaining, receipt.floor),
        (requested, remaining, floor)
    );
    (first, sticky)
}
#[test]
fn actual_cold_warm_unit_general_banks_exact_short_zero_floor_match_primitive_six_fields_and_drop()
{
    let f = function();
    for weight in [1, 2] {
        let (a, sink, root) = graph(&f, 4, 1, false);
        for requested in [COLD_RECEIVING, WARM_RECEIVING] {
            let mut limit = 0;
            let mut prefix = None;
            for _ in 0..10000 {
                let run = observe(
                    false,
                    &f,
                    &a,
                    sink,
                    root,
                    weight,
                    limit,
                    0,
                    MAX_REPLAY_WORK_UNITS,
                );
                let receipt = run.3.expect(
                    "finite staircase reaches real acquisition before successful completion",
                );
                let branch = usize::from(weight == 1);
                if receipt.requested == requested
                    && run.0 .0.report.cells[1][1][branch].refused == 1
                {
                    prefix = Some(run.2);
                    break;
                }
                limit = run.2.checked_add(receipt.requested).unwrap();
            }
            let prefix = prefix.expect("actual unit/general cold/warm bank must execute");
            let exact = prefix.checked_add(requested).unwrap();
            assert!(
                observe(
                    false,
                    &f,
                    &a,
                    sink,
                    root,
                    weight,
                    exact,
                    0,
                    MAX_REPLAY_WORK_UNITS
                )
                .2 >= exact
            );
            for (limit, floor, remaining) in [
                (prefix, 0, 0),
                (exact - 1, 0, requested - 1),
                (exact, 1, requested),
            ] {
                let run = observe(
                    false,
                    &f,
                    &a,
                    sink,
                    root,
                    weight,
                    limit,
                    floor,
                    MAX_REPLAY_WORK_UNITS,
                );
                assert!(run.1);
                assert_eq!(run.2, prefix);
                let receipt = run.3.unwrap();
                assert_eq!(
                    (receipt.requested, receipt.remaining, receipt.floor),
                    (requested, remaining, floor)
                );
                let expected = primitive(&f, requested, remaining, floor);
                assert_eq!(run.0 .0.result.as_ref().err(), Some(&expected.0));
                assert_eq!(run.0 .0.sticky.as_ref(), Some(&expected.1));
                let again = observe(
                    false,
                    &f,
                    &a,
                    sink,
                    root,
                    weight,
                    limit,
                    floor,
                    MAX_REPLAY_WORK_UNITS,
                );
                assert_eq!(
                    (
                        &run.0 .0.result,
                        run.0 .0.ordinary,
                        run.0 .0.skeleton,
                        run.0 .0.spent,
                        &run.0 .0.sticky
                    ),
                    (
                        &again.0 .0.result,
                        again.0 .0.ordinary,
                        again.0 .0.skeleton,
                        again.0 .0.spent,
                        &again.0 .0.sticky
                    )
                );
                assert_eq!(
                    (run.0 .1, run.1, run.2, run.3, run.4),
                    (again.0 .1, again.1, again.2, again.3, again.4)
                );
                assert_eq!(run.0 .0.report.cells, again.0 .0.report.cells);
                assert!(run.0 .0.report.complete && again.0 .0.report.complete);
            }
        }
    }
}
